WITH Sales(g,qty) AS (VALUES ('A',2),('A',3),('B',4),('C',1))
SELECT g,SUM(qty) AS total FROM Sales
GROUP BY g HAVING SUM(qty)>=5 ORDER BY g;

WITH T(id,score) AS (VALUES (1,5),(2,9),(3,9))
SELECT id,ROW_NUMBER() OVER (ORDER BY score DESC,id ASC) AS rn
FROM T ORDER BY id;

WITH S(g,amount) AS (VALUES ('A',2),('A',8),('B',6),('B',7),('C',4))
SELECT g,SUM(amount) AS total FROM S WHERE amount>=5
GROUP BY g HAVING COUNT(*)>=2 ORDER BY g;

WITH P(id) AS (VALUES (1),(2),(3)),
B(id) AS (VALUES (2),(NULL))
SELECT id FROM P WHERE id NOT IN (SELECT id FROM B) ORDER BY id;

WITH E(id,dept,score) AS (VALUES (1,'A',90),(2,'A',90),(3,'A',80),(4,'B',70)),
W AS (SELECT id,dept,ROW_NUMBER() OVER (PARTITION BY dept ORDER BY score DESC,id) AS rn FROM E)
SELECT dept,id,rn FROM W WHERE rn<=2 ORDER BY dept,rn;

WITH E(id,salary) AS (VALUES (1,100),(2,100),(3,90),(4,80)),
W AS (SELECT id,salary,DENSE_RANK() OVER (ORDER BY salary DESC) AS dr FROM E)
SELECT id,salary FROM W WHERE dr=2 ORDER BY id;

WITH T(id,g,v) AS (VALUES (1,'A',10),(2,'A',20),(3,'B',30))
SELECT id,LEAD(v,1,-1) OVER (PARTITION BY g ORDER BY id) AS nxt
FROM T ORDER BY id;

WITH T(id) AS (VALUES (1),(2),(3)),
R(id) AS (VALUES (2),(2),(NULL))
SELECT id FROM T WHERE id IN (SELECT id FROM R) ORDER BY id;
